package top.aameow.management.mapper;
import java.util.*;import org.apache.ibatis.annotations.*;
public interface ReimbursementMapper {
 String F="<where><if test='dateFrom!=null and dateFrom!=&quot;&quot;'>and r.expense_date &gt;= #{dateFrom}</if><if test='dateTo!=null and dateTo!=&quot;&quot;'>and r.expense_date &lt;= #{dateTo}</if><if test='userId!=null'>and r.user_id=#{userId}</if><if test='projectId!=null'>and r.project_id=#{projectId}</if><if test='source!=null and source!=&quot;&quot;'>and r.source=#{source}</if><if test='status!=null and status!=&quot;&quot;'>and r.status=#{status}</if><if test='name!=null and name!=&quot;&quot;'>and (r.purpose like concat('%',#{name},'%') or r.claimant_name like concat('%',#{name},'%') or r.receipt=#{name})</if></where>";
 String C="r.id,r.receipt,cast(r.amount as char) amount,r.purpose,r.project_id projectId,p.project_name projectName,p.project_no projectNo,r.user_id userId,r.claimant_name claimantName,date_format(r.expense_date,'%Y-%m-%d') expenseDate,r.remark,r.invoices,r.source,r.status,r.version,r.created_at createdAt,r.created_by createdBy,r.legacy_cost_id legacyCostId";
 @Select("<script>select "+C+" from zj_reimbursement r left join zj_work_project p on p.id=r.project_id "+F+" order by r.expense_date desc,r.id desc</script>") List<Map<String,Object>> list(Map<String,Object> q);
 @Select("select "+C+",r.legacy_snapshot legacySnapshot from zj_reimbursement r left join zj_work_project p on p.id=r.project_id where r.id=#{id}") Map<String,Object> get(Long id);
 @Select("select receipt,request_hash requestHash from zj_reimbursement where client_token=#{token}") Map<String,Object> receipt(String token);
 @Insert("insert into zj_reimbursement(receipt,client_token,request_hash,amount,purpose,project_id,user_id,claimant_name,expense_date,remark,source,created_by) values(#{receipt},#{clientToken},#{requestHash},#{amount},#{purpose},#{projectId},#{userId},#{claimantName},#{expenseDate},#{remark},#{source},#{actor})") @Options(useGeneratedKeys=true,keyProperty="id") int add(Map<String,Object> v);
 @Update("update zj_reimbursement set invoices=#{files} where id=#{id}") int invoices(@Param("id") Long id,@Param("files") String urls);
 @Update("update zj_reimbursement set status=#{status},version=version+1 where id=#{id} and version=#{version}") int status(Map<String,Object> v);
 @Select("<script>select count(*) records,cast(coalesce(sum(r.amount),0) as char) totalAmount,cast(coalesce(sum(case when r.status='pending' then r.amount else 0 end),0) as char) pendingAmount,cast(coalesce(sum(case when r.status='paid' then r.amount else 0 end),0) as char) paidAmount from zj_reimbursement r "+F+"</script>") Map<String,Object> summary(Map<String,Object> q);
 @Select("<script>select date_format(r.expense_date,'%Y-%m') label,count(*) records,cast(sum(r.amount) as char) amount from zj_reimbursement r "+F+" group by date_format(r.expense_date,'%Y-%m') order by label</script>") List<Map<String,Object>> months(Map<String,Object> q);
 @Select("<script>select coalesce(r.claimant_name,'历史人员待确认') label,count(*) records,cast(sum(r.amount) as char) amount from zj_reimbursement r "+F+" group by r.user_id,r.claimant_name order by sum(r.amount) desc</script>") List<Map<String,Object>> people(Map<String,Object> q);
 @Select("<script>select coalesce(p.project_name,'未关联项目') label,count(*) records,cast(sum(r.amount) as char) amount from zj_reimbursement r left join zj_work_project p on p.id=r.project_id "+F+" group by r.project_id,p.project_name order by sum(r.amount) desc</script>") List<Map<String,Object>> projectsSummary(Map<String,Object> q);
 @Select("select user_id id,nick_name name from sys_user where status='0' and del_flag='0' and user_id<>1 and lower(user_name)<>'admin' and (nick_name like concat('%',#{name},'%') or user_name like concat('%',#{name},'%')) order by nick_name,user_id limit 50") List<Map<String,Object>> users(String name);
 @Select("select id,project_name name,project_no code,project_type projectType from zj_work_project where project_name like concat('%',#{name},'%') or project_no like concat('%',#{name},'%') order by id desc limit 20") List<Map<String,Object>> projects(String name);
 @Select("select nick_name from sys_user where user_id=#{id} and user_id<>1 and lower(user_name)<>'admin' and status='0' and del_flag='0'") String userName(Long id);
 @Select("select id from zj_work_project where id=#{id}") Long project(Long id);
}
